<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import * as maplibregl from 'maplibre-gl'
import type { GeoJSONSource } from 'maplibre-gl'
import mapWorkerUrl from 'maplibre-gl/dist/maplibre-gl-worker.mjs?worker&url'
import 'maplibre-gl/dist/maplibre-gl.css'
import { MapPin, CalendarDays, Satellite, X } from '@lucide/vue'
import type { Analysis, Point } from '../huanuco'
const props=defineProps<{analysis: Analysis | null; confidence:string; fireType:string; year:number}>()
maplibregl.setWorkerUrl(mapWorkerUrl)
const selectedDate=ref(props.year === 2026 ? '2026-11-13' : props.year+'-09-30'), period=ref('week'), mapElement=ref<HTMLDivElement>()
const data=ref<Point[]>([]), selected=ref<Point | null>(null), error=ref(''), busy=ref(false), truncated=ref(false)
let map: maplibregl.Map | undefined, requestId=0
watch(() => props.year, y => { selectedDate.value = y === 2026 ? '2026-11-13' : y + '-09-30' }, {flush:'sync'})
const range=computed(() => { const end=selectedDate.value; const start=new Date(end+'T00:00:00Z'); if(period.value==='week')start.setUTCDate(start.getUTCDate()-6); if(period.value==='month')start.setUTCDate(1); return {start: start.toISOString().slice(0,10)< props.year+'-01-01'?props.year+'-01-01':start.toISOString().slice(0,10),end} })
function draw(){const source=map?.getSource('detections') as GeoJSONSource | undefined;source?.setData({type:'FeatureCollection',features:data.value.map(d=>({type:'Feature',geometry:{type:'Point',coordinates:[d.longitude,d.latitude]},properties:{id:d.id,sensor:d.sensor}}))})}
watch([range,()=>props.confidence,()=>props.fireType],async()=>{const id=++requestId;busy.value=true;error.value='';selected.value=null
try{const q=new URLSearchParams({...range.value,confidence:props.confidence,fire_type:props.fireType});const r=await fetch('/api/huanuco/points?'+q);if(!r.ok)throw new Error('No se pudieron cargar las observaciones.');const result=await r.json();if(id!==requestId)return;data.value=result.data;truncated.value=result.truncated;draw()}catch(e){if(id!==requestId)return;data.value=[];draw();error.value=e instanceof Error?e.message:'Error de conexión'}finally{if(id===requestId)busy.value=false}}, {immediate:true})
onMounted(async()=>{try{const response=await fetch('/geo/peru-departments.geojson');if(!response.ok)throw new Error('No se pudo cargar el límite de Huánuco.');const json=await response.json();const region=json.features.find((f:{properties:{shapeISO:string}})=>f.properties.shapeISO==='PE-HUC');if(!region||!mapElement.value)throw new Error('No se encontró el límite de Huánuco.');map=new maplibregl.Map({container:mapElement.value,center:[-76.2,-9.5],zoom:6,style:{version:8,sources:{imagery:{type:'raster',tiles:['https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}'],tileSize:256,attribution:'Imagery © Esri, Maxar, Earthstar Geographics'},region:{type:'geojson',data:region},detections:{type:'geojson',data:{type:'FeatureCollection',features:[]}}},layers:[{id:'background',type:'background',paint:{'background-color':'#c5d8c2'}},{id:'imagery',type:'raster',source:'imagery'},{id:'region',type:'fill',source:'region',paint:{'fill-color':'#c3e9c1','fill-opacity':0.12}},{id:'border',type:'line',source:'region',paint:{'line-color':'#fff','line-width':2}},{id:'points',type:'circle',source:'detections',paint:{'circle-radius':['interpolate',['linear'],['zoom'],5,3,10,6],'circle-color':['match',['get','sensor'],'MODIS','#ffd65a','#ef453e'],'circle-stroke-color':'#fff','circle-stroke-width':1}}]}});map.addControl(new maplibregl.NavigationControl(),'top-right');map.on('load',draw);map.on('click','points',e=>{const id=Number(e.features?.[0]?.properties?.id);selected.value=data.value.find(d=>d.id===id)??null});map.on('mouseenter','points',()=>{if(map)map.getCanvas().style.cursor='pointer'});map.on('mouseleave','points',()=>{if(map)map.getCanvas().style.cursor=''})}catch(e){error.value=e instanceof Error?e.message:'No se pudo iniciar el mapa.'}})
onUnmounted(()=>{requestId++;map?.remove()})
</script>
<template><div class="map-panel">
<div class="map-toolbar huanuco-toolbar"><label><CalendarDays :size="17"/>Fecha de referencia <input v-model="selectedDate" type="date" :min="year+'-01-01'" :max="year+'-12-31'"/></label><label>Periodo<select v-model="period"><option value="today">Día</option><option value="week">Últimos 7 días</option><option value="month">Mes hasta la fecha</option></select></label><span class="toolbar-source"><MapPin :size="16"/>Huánuco · {{ range.start }} a {{ range.end }} UTC</span></div>
<div class="map-workspace" :class="{'with-detail':selected}"><section class="map-stage" aria-label="Mapa de Huánuco"><div ref="mapElement" class="map-canvas" aria-label="Mapa de detecciones de Huánuco"/><div class="map-top-left"><div class="scope-summary"><div class="summary-title"><span class="status-dot"/>HUÁNUCO <span>· {{ year }}</span></div><dl><div><dt>Detecciones mostradas</dt><dd>{{ busy?'…':error?'—':data.length.toLocaleString('es-PE') }}</dd></div><div><dt>Área seleccionada</dt><dd>Departamento</dd></div></dl><p>{{ busy?'Consultando…':'Centros de píxeles · UTC' }}</p><p v-if="truncated">Se muestran los 20.000 puntos más recientes.</p></div></div><div class="map-bottom-left"><div class="map-legend"><h4>Sensor</h4><div><span><i style="background:#ffd65a"/>MODIS</span><span><i style="background:#ef453e"/>VIIRS Suomi</span></div><small>Selecciona un punto para ver sus datos.</small></div></div><div v-if="error" class="tile-notice" role="alert">{{ error }}</div></section>
<aside v-if="selected" class="detail-panel observation-detail"><button class="icon-button" aria-label="Cerrar detalle" @click="selected=null"><X :size="19"/></button><span class="eyebrow">OBSERVACIÓN SATELITAL</span><h2>Huánuco</h2><p>{{ selected.sensor }} · {{ selected.satellite }}</p><dl class="data-list"><div><dt>Fecha UTC</dt><dd>{{ selected.acquired_at }}</dd></div><div><dt>Coordenadas</dt><dd>{{ selected.latitude.toFixed(4) }}, {{ selected.longitude.toFixed(4) }}</dd></div><div><dt>FRP</dt><dd>{{ selected.frp === null ? 'Sin dato' : selected.frp.toFixed(1)+' MW' }}</dd></div><div><dt>Confianza original</dt><dd>{{ selected.confidence }}</dd></div><div><dt>Producto</dt><dd>{{ selected.version }} · {{ selected.source_kind }}</dd></div></dl><p class="inline-note">Una observación no es un incendio único ni confirma su causa.</p></aside></div><p class="fine-print">Sin puntos no confirma ausencia de fuego. El último dato disponible de VIIRS es {{ analysis?.ends.VIIRS ?? 'desconocido' }}; MODIS: {{ analysis?.ends.MODIS ?? 'desconocido' }}.</p></div></template>
